package app.tonal.android;

import android.app.*;
import android.graphics.*;
import android.widget.*;
import org.json.*;

final class LyricAppearance {
    static final String[] MODES={"Aurora","Ondas","Espectro","Capa","Foto","Estrelas","Chuva","Orbitas","Pulso","Grade","Sem animação"};
    static Typeface font(String name){return Typeface.create(name.equals("Serif")?"serif":name.equals("Mono")?"monospace":name.equals("Rounded")?"sans-serif-rounded":"sans-serif",Typeface.NORMAL);}
    static final class Verse extends TextView {
        String effect="Normal";int outline=0xff101722;boolean outlinePass;
        Verse(Activity a){super(a);setIncludeFontPadding(true);}
        protected void onDraw(Canvas c){if(effect.equals("Contorno")||effect.equals("Neon")){int color=getCurrentTextColor();getPaint().setStyle(Paint.Style.STROKE);getPaint().setStrokeJoin(Paint.Join.ROUND);getPaint().setStrokeWidth(getResources().getDisplayMetrics().density*2);getPaint().setColor(outline);int checkpoint=c.save();c.translate(getCompoundPaddingLeft(),getExtendedPaddingTop());if(getLayout()!=null)getLayout().draw(c);c.restoreToCount(checkpoint);getPaint().setStyle(Paint.Style.FILL);getPaint().setColor(color);}super.onDraw(c);}
    }
    static Verse verse(Activity a,String text){Verse v=new Verse(a);v.setText(text);return v;}
    static void apply(TextView view,JSONObject style,boolean translation){String prefix=translation?"translation":"lyric";int face=(style.optBoolean(prefix+"Bold")?Typeface.BOLD:0)|(style.optBoolean(prefix+"Italic")?Typeface.ITALIC:0);view.setTypeface(font(style.optString(prefix+"Font")),face);view.setTextColor(Color.parseColor(style.optString(prefix+"Color")));view.setTextSize(style.optInt(prefix+"Size"));view.setPaintFlags(style.optBoolean(prefix+"Underline")?view.getPaintFlags()|Paint.UNDERLINE_TEXT_FLAG:view.getPaintFlags()&~Paint.UNDERLINE_TEXT_FLAG);String effect=style.optString(prefix+"Effect","Normal");view.setShadowLayer(effect.equals("Brilho")||effect.equals("Neon")?6*view.getResources().getDisplayMetrics().density:0,0,0,Color.parseColor(style.optString(prefix+"OutlineColor","#101722")));if(view instanceof Verse){((Verse)view).effect=effect;((Verse)view).outline=Color.parseColor(style.optString(prefix+"OutlineColor","#101722"));}view.invalidate();}
    static void animate(TextView v,JSONObject style,boolean translation,boolean playing,long now){v.setAlpha(playing&&style.optString((translation?"translation":"lyric")+"Effect").equals("Piscante")?(now/650%2==0?1f:.4f):1f);}
    static void show(Activity a,MusicStore store,Runnable changed){Ui ui=new Ui(a);LinearLayout body=ui.column();ui.pad(body,18,12);JSONObject style=store.lyricStyle();
        for(String prefix:new String[]{"lyric","translation"}){body.addView(ui.title(prefix.equals("lyric")?"Letra original":"Tradução",20));String[] fonts={"Sans","Serif","Mono","Rounded"};Spinner font=new Spinner(a);font.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,fonts));for(int i=0;i<fonts.length;i++)if(fonts[i].equals(style.optString(prefix+"Font")))font.setSelection(i);font.setContentDescription("Fonte da "+(prefix.equals("lyric")?"letra":"tradução"));font.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){store.setLyricStyle(prefix+"Font",fonts[n]);changed.run();}});body.addView(font);
            EditText custom=new EditText(a);custom.setSingleLine();custom.setHint("Cor hexadecimal #RRGGBB");custom.setText(style.optString(prefix+"Color"));custom.setTextColor(Ui.TEXT);
            LinearLayout colors=ui.row();for(String color:new String[]{"#F5F5F5","#CEE9F0","#7DDBFF","#FFE39C","#FFBBD9","#AEE8B7"}){TextView swatch=ui.text("●",28,Color.parseColor(color));swatch.setGravity(android.view.Gravity.CENTER);swatch.setContentDescription("Cor "+color+" da "+prefix);ui.clickable(swatch,()->{custom.setText(color);custom.setSelection(custom.length());store.setLyricStyle(prefix+"Color",color);changed.run();});ui.weight(colors,swatch);}body.addView(colors);
            body.addView(custom);body.addView(ui.action("Aplicar cor",()->{String c=custom.getText().toString().trim();if(c.matches("#[0-9a-fA-F]{6}")){store.setLyricStyle(prefix+"Color",c);changed.run();}else custom.setError("Use #RRGGBB");}));
            SeekBar size=new SeekBar(a);ui.seek(size);size.setMax(28);size.setProgress(style.optInt(prefix+"Size")-16);size.setContentDescription("Tamanho da "+prefix);size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){if(user){store.setLyricStyle(prefix+"Size",16+value);changed.run();}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});body.addView(size);
            body.addView(ui.text("Contorno / brilho",14,Ui.MUTED));EditText outline=new EditText(a);outline.setSingleLine();outline.setText(style.optString(prefix+"OutlineColor"));outline.setTextColor(Ui.TEXT);body.addView(outline);LinearLayout strokes=ui.row();for(String color:new String[]{"#101722","#FFFFFF","#00C9FF","#FF4FBC","#FFC857"}){TextView dot=ui.text("●",28,Color.parseColor(color));dot.setGravity(android.view.Gravity.CENTER);ui.clickable(dot,()->{outline.setText(color);store.setLyricStyle(prefix+"OutlineColor",color);changed.run();});ui.weight(strokes,dot);}body.addView(strokes);body.addView(ui.action("Aplicar contorno",()->{String c=outline.getText().toString().trim();if(c.matches("#[0-9a-fA-F]{6}")){store.setLyricStyle(prefix+"OutlineColor",c);changed.run();}else outline.setError("Use #RRGGBB");}));
            String[] effects={"Normal","Contorno","Brilho","Neon","Piscante"};Spinner effect=new Spinner(a);effect.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,effects));for(int i=0;i<effects.length;i++)if(effects[i].equals(style.optString(prefix+"Effect")))effect.setSelection(i);effect.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){store.setLyricStyle(prefix+"Effect",effects[n]);changed.run();}});body.addView(effect);
            LinearLayout flags=ui.row();for(String flag:new String[]{"Bold","Italic","Underline"}){CheckBox check=new CheckBox(a);check.setText(flag.equals("Bold")?"Negrito":flag.equals("Italic")?"Itálico":"Sublinhar");check.setTextColor(Ui.TEXT);check.setTextSize(12);check.setChecked(style.optBoolean(prefix+flag));check.setOnCheckedChangeListener((v,on)->{store.setLyricStyle(prefix+flag,on);changed.run();});ui.weight(flags,check);}body.addView(flags);ui.space(body,20);
        }ScrollView scroll=new ScrollView(a);scroll.addView(body);new AlertDialog.Builder(a).setTitle("Fontes e cores das letras").setView(scroll).setPositiveButton("Concluir",null).show();
    }
}
